import{_ as i,l,o as e,c as n,v as t,p,x as r,d as P,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"迭代与在线 DPO","description":"","frontmatter":{"title":"迭代与在线 DPO","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/iterative-online-dpo.md","filePath":"llm/iterative-online-dpo.md","lastUpdated":1789023840000}'),h={name:"llm/iterative-online-dpo.md"};function m(D,a,_,O,c,f){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="迭代与在线-dpo" tabindex="-1">迭代与在线 DPO <a class="header-anchor" href="#迭代与在线-dpo" aria-label="Permalink to &quot;迭代与在线 DPO&quot;">​</a></h1><div class="epigraph"><p>离线偏好对来自旧策略；策略一走远，成对数据过期。迭代生成再标注，等于把 DPO 接回 on-policy 环。</p><footer>—— Rafailov 等 DPO 的离线设定；迭代 DPO / 在线偏好（Snorkel、Intel、后续 on-policy DPO 变体）把教师换成当前 π</footer></div><p><a href="/llm/train-infer-mismatch">上一课</a>收束 PPO/GRPO 的系统偏差。本单元问：没有更多人类比较时，监督从哪来。<a href="/llm/dpo">DPO</a> 默认吃固定 \\((y_w,y_l)\\)。缺口是：<strong>最优策略一旦离开造对分布，离线 DPO 在过期对上拟合，等于 off-policy 偏好学习。</strong> 本课写迭代与在线 DPO，不重导 BT 回代。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DPO 假设比较由当前关心的 \\(r\\) 在 \\(\\pi_{\\mathrm{ref}}\\) 邻域产生。公开偏好集来自 ChatGPT 或其他教师，\\(\\pi_{\\mathrm{ref}}\\) 对两条 \\(y\\) 概率都极低，梯度噪。即使对来自自己的 SFT，一轮 DPO 之后 \\(\\pi_\\theta\\) 已变，继续在旧对上多 epoch，就是对过期行为分布做极大似然。迭代：用当前策略采样候选，再请人、RM 或 LLM 裁判标序，换成新对，更新 \\(\\pi_{\\mathrm{ref}}\\) 或保持冻结。在线：每步或每批都重新造对，更接近 <a href="/llm/ppo-llm">PPO</a> 的数据流，只是损失仍是 DPO。</p><p>Dong 等 RSO、迭代 DPO 的工业复现，都在补这条分布缺口。它不自动解决 <a href="/llm/rm-overoptimization">过优化</a>：裁判若是旧 RM，迭代只是更快榨干 RM。每轮提示集也应刷新或重加权，否则只是对同一批 \\(x\\) 反复打磨，看起来在线、实际题面离线。</p><h3 id="参考策略跟不跟" tabindex="-1">参考策略跟不跟 <a class="header-anchor" href="#参考策略跟不跟" aria-label="Permalink to &quot;参考策略跟不跟&quot;">​</a></h3><p>每轮把 \\(\\pi_{\\mathrm{ref}}\\) 改成上一轮 \\(\\pi\\)，邻域跟着走，KL 意义变成「相对昨天」，能力可以走远，也更容易崩。冻结最初 SFT 当 ref，更像 InstructGPT 的锚。必须声明。在线 DPO 文献里两种都有。</p><p><span class="marginnote">用 RM 打分造对，再 DPO，不是「无奖励模型」；只是 RM 不进 PPO。过优化曲线仍然适用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一轮：\\(\\pi\\) 对每个 \\(x\\) 采 \\(K\\) 条 → 裁判或 RM 排序 → 取最好/最差或所有胜负对 → DPO 若干步 → （可选）更新 ref。金标抽检每轮都做，防止代理分涨、人降。在线小 batch 时，学习率低于离线，因为对的噪声大。与 RLHF 第三阶段对照：PPO 用标量 \\(r\\)；这里用序。两者都要新样本。</p>',11)),(e(),p(d,null,{default:r(()=>[s(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PI%5B%22%E5%BD%93%E5%89%8D%20%CF%80%22%5D%20--%3E%20SAMP%5B%22%E9%87%87%E6%A0%B7%20K%20%E6%9D%A1%22%5D%0A%20%20SAMP%20--%3E%20JUD%5B%22%E4%BA%BA%20%2F%20RM%20%2F%20%E8%A3%81%E5%88%A4%E6%A0%87%E5%BA%8F%22%5D%0A%20%20JUD%20--%3E%20PAIR%5B%22%E6%96%B0%20(y_w%2C%20y_l)%22%5D%0A%20%20PAIR%20--%3E%20DPO%5B%22DPO%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20DPO%20--%3E%20PI%0A%20%20GOLD%5B%22%E4%BA%BA%E7%B1%BB%E6%8A%BD%E6%A3%80%22%5D%20--%3E%20STOP%5B%22%E8%BF%87%E4%BC%98%E5%8C%96%E5%88%99%E5%81%9C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[P(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>迭代把 DPO 从「一次监督」变成偏好版 on-policy。梯度始终在当前会说的话上比较，避免对数比噪声。走得远的能力来自采样覆盖，不是来自损失形式。若 \\(K\\) 小、温度低，候选几乎相同，对没有信息，退化成空转——与 GRPO 全对组同一病。</p><p><span class="marginnote">自奖励（下一课）是把 JUD 换成模型自己；本课仍假设外部序。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>人类每轮标，贵，很快碰到可扩展监督问题。RM 或 LLM 裁判迭代，便宜，Goodhart 更快。混合：多数对由 AI 标，少数由人校准 RM。无 KL 的 PPO 与在线 DPO 在可验证域上常不如直接 GRPO；本课主场是开放偏好。下一课去掉外部裁判。</p><p>每轮都要外部金标抽检；提示集也要刷新，否则名为在线、题面仍离线。π_ref 冻结还是跟随必须声明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离线 DPO 对过期；迭代/在线用当前 π 造对，接回 on-policy。</li><li>造对的裁判若是 RM，过优化仍在。</li><li>\\(\\pi_{\\mathrm{ref}}\\) 冻结或跟随必须声明。</li><li>候选无分叉则对无信息，需温度与 \\(K\\)。</li><li>出处：Rafailov 等 DPO；迭代 DPO 工业配方；Dong 等 RSO；对照 Ouyang PPO 的在线样本。</li></ul>',8))])}const B=i(h,[["render",m]]);export{A as __pageData,B as default};
